void saiki(int x, int y) {
    stack<pair<int, int>> s;
    s.push({x, y});
    while (!s.empty()) {
        auto [cx, cy] = s.top();
        s.pop();
        if (masu[cx][cy] == 0) continue;
        masu[cx][cy] = 0; // Mark as visited
