        if (masu[cx + 1][cy] == 1) s.push({cx + 1, cy});
        if (masu[cx][cy + 1] == 1) s.push({cx, cy + 1});
        if (masu[cx - 1][cy] == 1) s.push({cx - 1, cy});
        if (masu[cx][cy - 1] == 1) s.push({cx, cy - 1});
    }
}

