    while (true) {
        fill(&masu[0][0], &masu[0][0] + sizeof(masu) / sizeof(masu[0][0]), 0);

        for (int i = 1; i <= 12; i++) {
            char st[13];
            if (scanf("%s", st) == EOF) return 0; // Exit on EOF
            for (int j = 0; j < 12; j++) {
                masu[i][j + 1] = st[j] == '0' ? 0 : 1;
            }
